25	// syntheticChain assumes a gapless, correctly fingerprinted chain.
26	func syntheticChain(org string, payloads []func(seq int) (string, *PolicyChange, *DecisionRecord)) ([]AuditRecord, Checkpoint) {
27		recs := make([]AuditRecord, 0, len(payloads))
28		prev := genesisFingerprint(org)
29		for i, build := range payloads {
30			seq := i + 1
31			kind, change, decision := build(seq)
32			r := syntheticRecord(org, seq, kind, change, decision, prev)
33			recs = append(recs, r)
34			prev = r.Fingerprint
35		}
36		return recs, Checkpoint{Org: org, EndSeq: len(recs), Fingerprint: prev}
37	}
